// ELEMENTS:
// 1. Fotografia no topo (src) com o corte diagonal iad em baixo e zoom lento
// 2. Monograma JC sobre o corte, à direita
// 3. Fundo claro #F7F8F8 com o título em coral maiúsculas (title) e filete dourado
// 4. Pontos (items, ou anim.text com uma linha / '|' por ponto), cada um com o visto iad desenhado
import React from "react";
import { AbsoluteFill, Img, useCurrentFrame, interpolate, spring, Easing } from "remotion";
import { loadFont as loadPoppins } from "@remotion/google-fonts/Poppins";
import type { PrimitiveProps } from "../primitives";

const { fontFamily: POPPINS } = loadPoppins("normal", { weights: ["700", "800"], subsets: ["latin", "latin-ext"] });

const SURFACE = "#F7F8F8";
const INK = "#213D56";
const PRIMARY = "#05B8E6";
const ACCENT = "#F06052";
const GOLD = "#CAA14D";
const RULE = "#DDE3E8";
const PHOTO_BG = "#B4B7B8";
const MONOGRAM = "data:image/webp;base64,";
const clamp = { extrapolateLeft: "clamp", extrapolateRight: "clamp" } as const;

// The iad tick pictogram: a short coral stroke into a long blue one, drawn in.
const Tick: React.FC<{ size: number; k: number }> = ({ size, k }) => (
  <svg width={size} height={size} viewBox="0 0 100 100" style={{ flexShrink: 0 }}>
    <path d="M22 54 L42 74" stroke={ACCENT} strokeWidth={16} strokeLinecap="round" fill="none"
      strokeDasharray={30} strokeDashoffset={30 * (1 - Math.min(1, k * 2))} />
    <path d="M42 74 L80 32" stroke={PRIMARY} strokeWidth={16} strokeLinecap="round" fill="none"
      strokeDasharray={60} strokeDashoffset={60 * (1 - Math.max(0, k * 2 - 1))} />
  </svg>
);

const ImagemListaPontos: React.FC<PrimitiveProps> = ({ anim, fps, frame: box }) => {
  const f = useCurrentFrame();
  const W = box.width;
  const H = box.height;
  const p = (anim.params ?? {}) as Record<string, unknown>;
  const str = (k: string): string => (p[k] == null ? "" : String(p[k]).trim());
  const src = str("src");
  const title = str("title");
  const raw: string[] = Array.isArray(p.items)
    ? (p.items as unknown[]).map((x) => String(x ?? ""))
    : String(anim.text ?? "").split(/\n|\|/);
  const items = raw.map((s) => s.trim()).filter(Boolean).slice(0, 6);

  // Laid out on a 540×960 stage, scaled to fit and centred.
  const u = Math.min(W / 540, H / 960);
  const ox = (W - 540 * u) / 2;
  const oy = (H - 960 * u) / 2;
  const total = Math.max(1, Math.round((anim.end - anim.start) * fps));
  const out = interpolate(f, [total - Math.round(0.4 * fps), total], [1, 0], clamp);
  const zoom = interpolate(f, [0, total], [1, 1.1], clamp);
  const photoIn = interpolate(f, [0, Math.round(0.5 * fps)], [0, 1], { ...clamp, easing: Easing.out(Easing.cubic) });

  const listAt = Math.round(0.45 * fps);
  const step = items.length
    ? Math.max(Math.round(0.15 * fps), Math.min(Math.round(0.6 * fps), Math.floor((total * 0.7 - listAt) / items.length)))
    : 0;
  const shrink = Math.max(0.7, Math.min(1, 1 - (items.length - 4) * 0.1));
  const itemSize = 24 * u * shrink;
  const tickSize = 52 * u * shrink;
  const head = spring({ frame: f - Math.round(0.25 * fps), fps, config: { damping: 18 } });
  const stamp = spring({ frame: f - Math.round(0.35 * fps), fps, config: { damping: 9, stiffness: 150 } });

  return (
    <AbsoluteFill style={{ background: SURFACE, overflow: "hidden", fontFamily: POPPINS, color: INK, opacity: out }}>
      <div
        style={{
          position: "absolute",
          left: 0,
          right: 0,
          top: 0,
          height: oy + 420 * u,
          overflow: "hidden",
          clipPath: `polygon(0 0, 100% 0, 100% ${86 * photoIn}%, 0 ${100 * photoIn}%)`,
          background: PHOTO_BG,
        }}
      >
        {src ? <Img src={src} style={{ width: "100%", height: "100%", objectFit: "cover", transform: `scale(${zoom})` }} /> : null}
      </div>
      <div style={{ position: "absolute", left: ox, top: oy, width: 540 * u, height: 960 * u }}>
        <Img
          src={MONOGRAM}
          style={{
            position: "absolute",
            right: 40 * u,
            top: 360 * u,
            width: 80 * u,
            height: 80 * u,
            opacity: interpolate(stamp, [0, 0.2], [0, 1], clamp),
            transform: `scale(${1.6 - 0.6 * stamp}) rotate(${(1 - stamp) * -14}deg)`,
          }}
        />
        <div style={{ position: "absolute", left: 40 * u, right: 40 * u, top: 460 * u, display: "flex", flexDirection: "column", gap: 6 * u }}>
          {title ? (
            <div style={{ fontSize: 14 * u, fontWeight: 800, letterSpacing: 4 * u, color: ACCENT, textTransform: "uppercase", opacity: head }}>{title}</div>
          ) : null}
          <div style={{ width: 64 * u * head, height: 3 * u, background: GOLD, marginBottom: 18 * u * shrink }} />
          {items.map((it, i) => {
            const start = listAt + i * step;
            const k = interpolate(f, [start, start + Math.round(0.4 * fps)], [0, 1], { ...clamp, easing: Easing.out(Easing.cubic) });
            return (
              <div
                key={i}
                style={{
                  display: "flex",
                  alignItems: "center",
                  gap: 14 * u,
                  padding: `${12 * u * shrink}px 0`,
                  borderBottom: i < items.length - 1 ? `${1 * u}px solid ${RULE}` : "none",
                  opacity: k,
                  transform: `translateX(${(1 - k) * -24 * u}px)`,
                }}
              >
                <Tick size={tickSize} k={k} />
                <div style={{ fontSize: itemSize, fontWeight: 700, lineHeight: 1.2 }}>{it}</div>
              </div>
            );
          })}
        </div>
      </div>
    </AbsoluteFill>
  );
};

export default ImagemListaPontos;

