              fontStyle: "italic",
              textTransform: "uppercase",
              fontSize: titleFs,
              lineHeight: 1.02,
              marginBottom: fs * 0.8,
              backgroundImage: headlineGradient(),
              backgroundClip: "text",
              WebkitBackgroundClip: "text",
              color: "transparent",
              overflowWrap: "break-word",
              opacity: interpolate(pTitle, [0, 0.4], [0, 1], clamp),
              translate: `0px ${(1 - pTitle) * fs}px`,
            }}
          >
            {title}
          </div>
        ) : null}
        {items.map((item, i) => {
          const p = pop(itemStart + i * step, 13);
          return (
            <div
              key={i}
              style={{
                display: "flex",
                alignItems: "flex-start",
                gap: fs * 0.55,
                marginTop: i === 0 ? 0 : fs * 0.75,
                opacity: interpolate(p, [0, 0.35], [0, 1], clamp),
