// Bullets come from params.items (array or "a|b" / newline string), else from anim.text.
const toItems = (raw: unknown, text: string): string[] => {
  const list = Array.isArray(raw)
    ? raw.map((x) => String(x ?? ""))
    : String(typeof raw === "string" && raw.trim() ? raw : text).split(/\n|\||•/);
