  const p = anim.params ?? {};
  const src = String(p.src ?? "");
  const title = String(p.title ?? "").trim();
  const items = toItems(p.items, String(anim.text ?? ""));
  const n = items.length;

  const land = format === "landscape";
  const half = format === "half";
  const u = land ? H / 1080 : W / 1080;
  const pad = (land ? 56 : half ? 48 : 72) * u;
  const slash = Math.min(W * 0.09, H * 0.08);

  // Shrink type for long lines and long lists so nothing is cut.
  const longest = Math.max(1, ...items.map((s) => s.length));
  const lenK = Math.max(0.6, Math.min(1, (land ? 28 : 36) / longest));
  const cap = land ? 4 : half ? 4 : 5;
  const countK = Math.max(0.6, Math.min(1, cap / Math.max(cap, n)));
  const bulletSize = (land ? 34 : half ? 32 : 42) * u * lenK * countK;
  const titleSize = (land ? 64 : half ? 54 : 80) * u * Math.max(0.55, Math.min(1, 22 / Math.max(22, title.length)));

  const panelIn = spring({ frame: f, fps, config: { damping: 200 }, durationInFrames: Math.round(0.7 * fps) });
  const outStart = Math.max(1, total - Math.round(0.4 * fps));
  const bulletStart = Math.round(0.8 * fps);
  const windowF = Math.max(1, total * 0.75 - bulletStart);
  const step = Math.min(0.7 * fps, windowF / Math.max(1, n));
