            border: `${Math.max(2, 3 * u)}px dashed ${COLORS.mutedOnLight}88`,
            background: "rgba(255,255,255,.06)",
            display: "flex",
            alignItems: "center",
            justifyContent: "center",
            color: COLORS.mutedOnLight,
            fontSize: 36 * u,
            fontWeight: FONTS.bodyWeight,
          }}
        >
          Imagem
        </div>
      )}

      {title || n > 0 ? (
        <div
          style={{
            position: "absolute",
            left: 0,
            right: 0,
            bottom: 0,
            minHeight: `${land ? 42 : half ? 50 : 44}%`,
            boxSizing: "border-box",
            background: COLORS.leather,
            clipPath: `polygon(0 ${slash}px, 100% 0, 100% 100%, 0 100%)`,
            padding: `${slash + pad * 0.7}px ${pad}px ${land || half ? pad : Math.max(pad, H * 0.12)}px`,
            display: "flex",
            flexDirection: "column",
            justifyContent: "center",
            translate: `0 ${(1 - panelIn) * 110}%`,
          }}
        >
          {title ? (
            <div
              style={{
                fontFamily: FONTS.display,
                fontWeight: FONTS.displayWeight,
                fontSize: titleSize,
                lineHeight: 0.98,
                textTransform: "uppercase",
                color: COLORS.gold,
                marginBottom: pad * 0.55,
                overflowWrap: "break-word",
                opacity: interpolate(f, [0.35 * fps, 0.8 * fps], [0, 1], { ...clamp, easing: ease }),
                translate: `0 ${interpolate(f, [0.35 * fps, 0.8 * fps], [24 * u, 0], { ...clamp, easing: ease })}px`,
              }}
            >
              {title}
            </div>
          ) : null}

          <div style={listStyle}>
            {items.map((item, i) => {
              const t0 = bulletStart + i * step;
              return (
                <div
                  key={i}
                  style={{
                    display: "flex",
                    alignItems: "flex-start",
                    gap: "0.55em",
                    flex: land ? "1 1 0" : undefined,
                    minWidth: land ? `${Math.min(28, 100 / Math.max(1, n))}%` : undefined,
                    fontSize: bulletSize,
                    lineHeight: 1.3,
                    color: "rgba(255,255,255,1)",
                    fontWeight: FONTS.bodyWeight,
                    opacity: interpolate(f, [t0, t0 + itemDur], [0, 1], { ...clamp, easing: ease }),
                    translate: `${interpolate(f, [t0, t0 + itemDur], [-40 * u, 0], { ...clamp, easing: ease })}px 0`,
                  }}
                >
